R=Path('/home/jack/git/TestReview');D=R/'docs/imports/new-gpt-20261104-a'; URL='https://chatgpt.com/share/6aea190f-d430-83ee-ab44-f243de7f2aec';SID='src-more-055';MS=json.load(open(R/'docs/sources/6aea190f-d430-83ee-ab44-f243de7f2aec.json'))['messages']; MAP={r['messageIndex']:r for r in json.load(open(D/'attachment-message-map.json'))}
