def table(caption,headers,rows):return dict(caption=caption,headers=headers,rows=rows)
def make(key,mi,num,title,stem,opts,ans,exp,analyses,tags,refs,student='',labels=None):
 labels=labels or list('ABCD');date=datetime.datetime.fromtimestamp(MS[mi]['create_time'],zoneinfo.ZoneInfo('Asia/Taipei'));pics=assets(mi)
 selected=set(ans.replace('、','').replace(',',''))
 return dict(id='gpt055-'+key,sourceId=SID,subject='Civics',title=title,chapter='綜合',volume='綜合',date=date.date().isoformat(),dateLabel='首次出題日期',question=stem+'\n'+'\n'.join(f'({k}) {t}' for k,t in zip(labels,opts)),answer='、'.join(f'({k}) {t}' for k,t in zip(labels,opts) if k in selected),explanation=exp,trap='',verification='原卷逐題核對',verificationNote='已實看真正上傳原卷及裁切成品，核對完整題幹、全部選項、必要表文與原卷訂正，並於2026-11-04核對官方法規。未確認教材對應冊次、章節，歸綜合。日期取原問首次訊息的台灣日期，非實際考試日期。',diagram='',tags=tags,images=pics,sourceLabel=f'分享原卷｜第{num}題',studentAnswer=student,contentStatus='完整原題',correctOption=ans,passage='',optionAnalysis=[dict(label=k,text=t,wordClass='應選' if k in selected else '不選',meaning='',explanation=a) for k,t,a in zip(labels,opts,analyses)],tables=[],questionFigures=[],explanationFigures=[],originalQuestionNumber=str(num),supportingSources=[dict(title=title,url=u) for title,u in refs],sourceEvidence=dict(url=URL,messageIndex=mi,messageId=MS[mi]['id'],firstQuestionTimestamp=MS[mi]['create_time'],firstQuestionDateTime=date.isoformat(),originalImage=MAP[mi]['path'],originalImageSHA256=MAP[mi]['sha256'],attachmentMatchedBy='archive size_bytes and fileId, not filename order',cropHashes={p:sha(p) for p in pics},inclusionEvidence='使用者原訊息指定「'+MAP[mi]['prompt']+'」，且此問原卷有紅筆訂正；已逐題實看。'))

def group(children,title,passage='',tables=None):
 p=copy.deepcopy(children[0]);p.update(title=title,question='\n\n'.join(f'【第{x["originalQuestionNumber"]}題】\n'+x['question'] for x in children),answer='\n'.join(f'【第{x["originalQuestionNumber"]}題】'+x['answer'] for x in children),explanation='\n\n'.join(f'【第{x["originalQuestionNumber"]}題】\n'+x['explanation'] for x in children),correctOption='',optionAnalysis=[],studentAnswer='\n'.join(f'【第{x["originalQuestionNumber"]}題】'+x['studentAnswer'] for x in children),originalQuestionNumber='、'.join(x['originalQuestionNumber'] for x in children),passage=passage,tables=tables or [],tags=list(dict.fromkeys(t for x in children for t in x['tags'])),groupQuestions=children,groupMetadata=dict(kind='original_paper',printedRange='同一原卷共同表格/選項，第'+ '、'.join(x['originalQuestionNumber'] for x in children)+'題',draftMembers=[x['id'] for x in children],representativeSubjectReason='各子題均屬同一公民共同材料，非僅因同科或相似題材合併。'))
 return p

q5=make('guardianship-q5',0,5,'公民第5題｜監護宣告後的行為能力',
'30歲的志強因意外造成心智缺陷而無法完全表達意思，家人為協助處理他的法律事務，提出監護宣告的聲請。當聲請通過後，會出現何種改變？',
['選總統投票時志強無權前往投票','志強購買便當不須經監護人同意','志強屬於《民法》上的無行為能力人','志強已達成年年齡，簽訂的契約有效'],'C',
'本題的關鍵不是志強已經30歲，而是法院已作成監護宣告。《民法》第15條規定，受監護宣告者沒有行為能力，所以選C。\n\n受監護宣告後，不能只因成年就認定他自行簽約有效。依第75、76條，無行為能力人的意思表示無效，原則上由法定代理人代為及代受意思表示。B想套用日常生活必需交易的例外，但第77條的這項例外是針對限制行為能力人，不能直接套在無行為能力人身上。\n\nA須依現行選舉法判斷。2023年6月9日修法已刪除總統、公職人員選舉中「受監護宣告尚未撤銷者無選舉權」的限制，符合其他法定資格者仍可投票。民法的行為能力、選舉權與候選人資格是不同制度，不能互相代換；此處也不把公民投票權的規定混入總統選舉。',
['現行總統選罷法第11條已不以監護宣告作為剝奪選舉權的原因，不能只憑監護宣告判定不能投總統票。','監護宣告後屬無行為能力，不能直接套用限制行為能力人的日常生活必需交易例外。','《民法》第15條直接規定受監護宣告者無行為能力，符合題意。','監護宣告的效果不因已成年消失，不能因此認定他自行簽訂的契約有效。'],
['監護宣告','無行為能力','選舉權','日常生活必需交易'],[('民法第15條',law('B0000001',15)),('民法第75、76、77條',law('B0000001',75)),('總統選罷法第11條',law('D0020053',11)),('中選會2023修法宣導','https://web.cec.gov.tw/api/file/5ffc121c-e569-4c3c-a805-df3da6a6a6ac.pdf')],'A；原卷紅筆訂正C。')
q5['sourceEvidence']['inclusionEvidence']='原訊息「30@錯題」依原圖是印刷第5題的「30歲」起句；後續訊息23明確稱「第五題」，為同題澄清，非另一題。原卷A遭劃除，紅筆C清楚。'

q11=make('capacity-q11',39,11,'公民第11題｜成年、監護與日常交易',
'有關《民法》上的行為能力，下列敘述何者正確？',
['18歲以上受監護宣告者仍是無行為能力人','國中生放學和同學一起吃飯須經過父母同意','男女年滿18歲須要經過父母同意才可以結婚','80歲以上精神健全的老人是限制行為能力人'],'A',
'先檢查是否受監護宣告，再看年齡。受監護宣告者依《民法》第15條無行為能力，即使已滿18歲也一樣，因此A正確。\n\n一般未成年國中生屬限制行為能力人，但依其年齡及身分的日常生活必需交易，可以不經法定代理人允許。一般吃飯消費符合這類例子；不能把所有未成年人的消費都說成必須先取得父母同意，也不能把這個例外擴大到所有昂貴消費。\n\n滿18歲已成年，結婚不以父母同意為必要；仍須符合其他結婚要件。高齡本身也不會讓人自動變成限制行為能力人。D已說精神健全，題目又未給其他特殊條件，不能只因80歲就改變行為能力分類。',
['受監護宣告者無行為能力，不因成年而排除。','一般日常吃飯消費屬符合年齡、身分的生活必需交易，不能一概要求父母先同意。','滿18歲已成年，結婚無須父母同意；仍須遵守書面、證人及戶政登記等要件。','年齡高不會自動使成年人變成限制行為能力人。'],
['成年','監護宣告','限制行為能力','結婚'],[('民法第12、13、15條',law('B0000001',12)),('民法第77條',law('B0000001',77)),('民法第980、982條',law('B0000001',982))],'D；原卷紅筆訂正A。')

q19=make('housing-q19',65,19,'公民第19題｜房屋糾紛的調解與訴訟',
'附表為113年房屋買賣消費糾紛的部分原因統計。根據表中內容判斷，下列敘述何者錯誤？',
['違反誠實信用原則是導致消費糾紛的原因之一','買方可向調解委員會提民事訴訟追究民事責任','房屋仲介或建商可能因債務不履行負賠償責任','此類消費須以書面契約簽訂並向政府機關登記'],'B',
'依原對話使用者後續明確更正，答案為B。調解委員會辦理的是調解；向調解委員會可以聲請調解，不能說向它「提民事訴訟」。民事起訴應向有管轄權的法院提出。法院也能辦理調解，但這不會讓調解委員會變成法院。\n\nA所說誠實信用，與「隱瞞重要資訊」可能引發交易糾紛相符。C用了「可能」，若仲介或建商未依約履行義務，又符合賠償要件，可能負債務不履行責任；不是發生任何糾紛就一定賠。\n\nD按本題房屋交易與所有權移轉的概括語境理解。因買賣而移轉不動產物權，須書面及登記；但「買賣契約成立」和「所有權移轉登記」不同，不能把D延伸成所有買賣契約都須登記才成立。保留原選項及這項措辭限制，不擅改原題，也不推翻來源使用者已明確更正的B。',
['隱瞞重要資訊可能違反誠信並造成糾紛，為合理敘述。','混淆機關與程序：調解委員會受理聲請調解，民事訴訟向法院提起，因此本題應選。','若符合不履行契約與損害賠償要件，仲介或建商可能負責；「可能」不是一律。','應限於房屋所有權因法律行為移轉的書面與登記要求；不將它誤教成一般買賣契約成立皆須登記。'],
['調解','民事訴訟','誠實信用','不動產登記'],[('鄉鎮市調解條例第1條',law('I0020003',1)),('民事訴訟法第244條',law('B0010001',244)),('民法第148、227、758條',law('B0000001',758))],'原卷黑筆C、紅筆D；來源後續使用者將答案改為B。')
q19['tables']=[table('113年房屋買賣消費糾紛部分原因（單位：件）',['原因','件數'],[['房屋漏水問題','52'],['終止委售或買賣契約','52'],['隱瞞重要資訊','34']])]
q19['sourceEvidence']['userCorrection']={'messageIndices':[81,86],'text':'答案改成b；請重新解答19題','disposition':'沿用來源使用者明確更正B，不重複請求同項確認；保留D措辭限制。'}

q26=make('laptop-q26',93,26,'公民第26題｜過失損壞電腦的民事責任',
'26歲的小李幫忙大學同學搬家時，不小心摔壞了同學的筆記型電腦。依《民法》規定，小李應如何處理？',
['因幫忙同學才摔壞電腦，法律上無須負民事責任','為限制行為能力人，因此他不須負損害賠償責任','為完全行為能力人，應以將電腦恢復原狀為原則','除了修好電腦還同學，其法定代理人負連帶責任'],'C',
'小李已26歲，依題目條件為完全行為能力人。「不小心摔壞」在本題指過失侵害同學財產權，仍可能成立民事損害賠償責任；好心幫忙或不是故意，都不等於一律免責。\n\n《民法》第213條以回復損害發生前的原狀為原則，因此可修復時，原則上將電腦修復，選C。同學也可以請求支付必要的修復費用，不是一定要小李親手修理。\n\nB先把26歲誤當限制行為能力人，而且限制行為能力人也不是一律不用賠。D則把未成年人及法定代理人的責任規則套到本題成年人；父母不會只因親子關係就自動負連帶賠償。',
['幫忙是出於善意，仍不能直接排除過失損害賠償責任。','小李依題意已成年且無監護等特殊條件，不屬限制行為能力人；受限制也不代表一律免賠。','成年者依題意自行負責，賠償以回復原狀為原則，符合民法第213條。','本題成年人自行負責，不能只憑親子關係要求父母負法定代理人的連帶責任。'],
['過失','損害賠償','回復原狀','完全行為能力'],[('民法第12條',law('B0000001',12)),('民法第184、187條',law('B0000001',184)),('民法第213條',law('B0000001',213))],'原作答字母遭劃除；紅筆訂正C。')

